const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const city = ee.Geometry.Point([-71.25, -29.90]); // La Serena, Chile
  const startYearHistorical = 1990;
  const endYearHistorical = 2020;
  const currentYear = new Date().getFullYear(); // Use current year for robustness, but question implies recent data.
  const startDay = '01-01';
  const endDay = '07-07';

  const startDateCurrent = ee.Date(currentYear + '-' + startDay);
  const endDateCurrent = ee.Date(currentYear + '-' + endDay);

  // 2. Data Acquisition
  const collection = ee.ImageCollection('UCSB-CHG/CHIRPS/PENTAD').select('precipitation');

  // 3. Processing: Calculate Historical Average
  // Create a list of years for the historical period
  const years = ee.List.sequence(startYearHistorical, endYearHistorical);

  // Function to calculate total rainfall for the period (Jan 1 - Jul 7) for a given year
  const calculateAnnualTotal = function(year) {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date(startDate.advance(ee.Date(currentYear + '-' + endDay).getRelative('day', 'year'), 'day'));
    const yearCollection = collection.filterDate(startDate, endDate);
    // Return the sum over the collection, which is a single image
    return yearCollection.sum().set('year', year).set('image_count', yearCollection.size());
  };

  // Map the function over the list of years
  const yearlyTotals = ee.ImageCollection.fromImages(years.map(calculateAnnualTotal));

  // Check if we have data for the historical period
  const historicalImagesCount = yearlyTotals.aggregate_sum('image_count').getInfo();
  if (historicalImagesCount === 0) {
      console.log('No historical CHIRPS images found for the specified date range.');
      console.log('A');
      return;
  }

  // Calculate the mean of the yearly totals
  const meanHistoricalRainfallImage = yearlyTotals.mean();
  const meanHistoricalRainfall = meanHistoricalRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: city,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');


  // 4. Processing: Calculate Current Year's Rainfall
  const currentCollection = collection.filterDate(startDateCurrent, endDateCurrent);
  const currentCollectionSize = currentCollection.size().getInfo();

  if (currentCollectionSize === 0) {
    console.log(`No CHIRPS images found for ${currentYear} up to ${endDay}.`);
    console.log('C1');
    return;
  }

  const currentRainfallImage = currentCollection.sum();
  const currentRainfall = currentRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: city,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // ee.Number objects require evaluation on the server, getInfo() brings them client-side
  const meanHistVal = ee.Number(meanHistoricalRainfall).getInfo();
  const currentVal = ee.Number(currentRainfall).getInfo();

  // 5. Validation & Final Answer
  if (meanHistVal === null || currentVal === null) {
      console.log('Failed to calculate rainfall values.');
      console.log(`Historical Mean: ${meanHistVal}, Current Total: ${currentVal}`);
      console.log('C3');
      return;
  }

  if (meanHistVal <= 0) { // Avoid division by zero for arid regions
      console.log(`Historical mean rainfall is zero or negative (${meanHistVal.toFixed(2)} mm). Cannot calculate deficit.`);
      console.log(`Current rainfall: ${currentVal.toFixed(2)} mm.`);
      console.log('B'); // A deficit is not "larger" than 40% if the baseline is zero.
      return;
  }

  const deficit = 1 - (currentVal / meanHistVal);
  const deficitPercent = deficit * 100;

  console.log(`Historical mean rainfall (Jan 1-Jul 7, 1990-2020): ${meanHistVal.toFixed(2)} mm`);
  console.log(`Current year-to-date rainfall (${currentYear}): ${currentVal.toFixed(2)} mm`);
  console.log(`Rainfall deficit: ${deficitPercent.toFixed(2)}%`);
  console.log(`Historical image segments found: ${historicalImagesCount}`);
  console.log(`Current year image segments found: ${currentCollectionSize}`);

  if (deficit > 0.40) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(`An error occurred: ${e}`);
  console.log('D');
});
